screenPanels.initJs:
function(container, apiUrl, tables) {
  let selectedCaseId = null;
  let selectedCaseData = null;

  // テーブルインデックス
  const CASE_TABLE = 0;
  const MARKET_TABLE = 1;
  const DEVIATION_TABLE = 2;
  const MATERIAL_TABLE = 3;
  const GENERATION_HISTORY_TABLE = 4;

  // DOM要素取得
  const caseIdInput = container.querySelector('[data-testid="case-id-input"]');
  const caseStatusSelect = container.querySelector('[data-testid="case-status-select"]');
  const searchCaseBtn = container.querySelector('[data-testid="search-case-button"]');
  const caseTbody = container.querySelector('#case-tbody');
  const selectedCasePanel = container.querySelector('#selected-case-panel');
  const analysisPanel = container.querySelector('#analysis-panel');
  const generationPanel = container.querySelector('#generation-panel');
  const deliveryPanel = container.querySelector('#delivery-panel');
  const templateSelect = container.querySelector('[data-testid="template-select"]');
  const previewBtn = container.querySelector('[data-testid="preview-button"]');
  const generateBtn = container.querySelector('[data-testid="generate-button"]');
  const viewAnalysisBtn = container.querySelector('[data-testid="view-analysis-button"]');
  const deliveryChannelSelect = container.querySelector('[data-testid="delivery-channel-select"]');
  const deliveryScheduleSelect = container.querySelector('[data-testid="delivery-schedule-select"]');
  const executeDeliveryBtn = container.querySelector('[data-testid="execute-delivery-button"]');
  const historyTbody = container.querySelector('#history-tbody');
  const previewModal = container.querySelector('#preview-modal');
  const analysisModal = container.querySelector('#analysis-modal');
  const successMsg = container.querySelector('#success-message');
  const errorMsg = container.querySelector('#error-message');

  // 案件検索
  searchCaseBtn.addEventListener('click', async () => {
    const caseId = caseIdInput.value.trim();
    const status = caseStatusSelect.value;

    const allCases = await window.aivicApi.list(CASE_TABLE);
    if (!allCases) return;

    let filtered = allCases;
    if (caseId) filtered = filtered.filter(c => c.id.includes(caseId) || c.査定対象品名.includes(caseId));
    if (status) filtered = filtered.filter(c => c.案件ステータス === status);

    caseTbody.innerHTML = filtered.length === 0 
      ? '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">該当する案件がありません</td></tr>'
      : filtered.map(c => `
        <tr style="border-bottom: 1px solid var(--border);" data-id="${c.id}">
          <td style="padding: 6px 8px;">${c.id.substring(0, 8)}</td>
          <td style="padding: 6px 8px;">${c.査定対象品名}</td>
          <td style="padding: 6px 8px; text-align: right;">¥${(c.査定額 || 0).toLocaleString()}</td>
          <td style="padding: 6px 8px;">${c.案件ステータス}</td>
          <td style="padding: 6px 8px; text-align: center;">
            <button class="select-case-btn" style="padding: 4px 8px; background: var(--primary); color: #fff; border: none; border-radius: 3px; font-size: 12px; cursor: pointer;">選択</button>
          </td>
        </tr>
      `).join('');

    // 案件選択ボタン
    container.querySelectorAll('.select-case-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const row = e.target.closest('[data-id]');
        const caseId = row.dataset.id;
        selectCase(caseId, filtered.find(c => c.id === caseId));
      });
    });
  });

  // 案件選択処理
  async function selectCase(caseId, caseData) {
    selectedCaseId = caseId;
    selectedCaseData = caseData;

    // 選択案件情報を表示
    container.querySelector('#selected-case-id').textContent = caseId.substring(0, 8);
    container.querySelector('#selected-case-name').textContent = caseData.査定対象品名;
    container.querySelector('#selected-case-amount').textContent = `¥${(caseData.査定額 || 0).toLocaleString()}`;
    container.querySelector('#selected-case-quality').textContent = caseData.品質評価 || '-';

    selectedCasePanel.style.display = 'block';

    // 相場・乖離分析データを取得
    const deviations = await window.aivicApi.list(DEVIATION_TABLE);
    if (deviations) {
      const deviation = deviations.find(d => d.査定案件ID === caseId);
      if (deviation) {
        container.querySelector('#market-price').textContent = `¥${(deviation.相場金額 || 0).toLocaleString()}`;
        container.querySelector('#deviation-rate').textContent = `${deviation.乖離率}%`;
        container.querySelector('#deviation-category').textContent = deviation.乖離区分 || '-';
        analysisPanel.style.display = 'block';
      }
    }

    generationPanel.style.display = 'block';
    deliveryPanel.style.display = 'block';
  }

  // 詳細分析表示
  viewAnalysisBtn.addEventListener('click', async () => {
    const deviations = await window.aivicApi.list(DEVIATION_TABLE);
    if (!deviations) return;

    const deviation = deviations.find(d => d.査定案件ID === selectedCaseId);
    if (deviation) {
      const content = `
        <div style="line-height: 1.8;">
          <p><strong>乖離金額:</strong> ¥${(deviation.乖離金額 || 0).toLocaleString()}</p>
          <p><strong>乖離率:</strong> ${deviation.乖離率}%</p>
          <p><strong>乖離区分:</strong> ${deviation.乖離区分}</p>
          <p><strong>品質判定:</strong> ${deviation.品質判定}</p>
          <p><strong>対応状況:</strong> ${deviation.対応状況}</p>
          <p><strong>乖離要因:</strong></p>
          <p style="margin-left: 12px; color: var(--text-muted);">${deviation.乖離要因 || '記載なし'}</p>
          <p><strong>対応内容:</strong></p>
          <p style="margin-left: 12px; color: var(--text-muted);">${deviation.対応内容 || '記載なし'}</p>
        </div>
      `;
      container.querySelector('#analysis-content').innerHTML = content;
      analysisModal.style.display = 'flex';
    }
  });

  // プレビュー表示
  previewBtn.addEventListener('click', () => {
    const template = templateSelect.value;
    const notes = container.querySelector('[data-testid="additional-notes"]').value;
    const graphs = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(c => c.value);

    const previewContent = `
      <div>
        <p><strong>テンプレート:</strong> ${template || '未選択'}</p>
        <p><strong>グラフ:</strong> ${graphs.length > 0 ? graphs.join(', ') : 'なし'}</p>
        <p><strong>補足説明:</strong></p>
        <p style="margin-left: 12px; white-space: pre-wrap; color: var(--text-muted);">${notes || '(なし)'}</p>
        <hr style="border: none; border-top: 1px solid var(--border); margin: 12px 0;">
        <p style="font-size: 12px; color: var(--text-muted);">この資料は以下の情報を含みます:</p>
        <ul style="margin: 8px 0; padding-left: 20px; font-size: 12px; color: var(--text-muted);">
          <li>査定案件: ${selectedCaseData.査定対象品名}</li>
          <li>査定額: ¥${(selectedCaseData.査定額 || 0).toLocaleString()}</li>
          <li>相場分析結果</li>
          <li>乖離分析結果</li>
        </ul>
      </div>
    `;
    container.querySelector('#preview-content').innerHTML = previewContent;
    previewModal.style.display = 'flex';
  });

  // 資料生成実行
  generateBtn.addEventListener('click', async () => {
    if (!selectedCaseId || !templateSelect.value) {
      showError('案件とテンプレートを選択してください');
      return;
    }

    const template = templateSelect.value;
    const notes = container.querySelector('[data-testid="additional-notes"]').value;
    const graphs = Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(c => c.value);

    const historyRecord = {
      査定案件ID: selectedCaseId,
      ユーザーID: 'current-user',
      グラフタイプ: graphs.join(',') || 'none',
      生成パラメータ: JSON.stringify({ template, notes }),
      生成ステータス: '成功',
      作成日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(GENERATION_HISTORY_TABLE, historyRecord);
    if (saved) {
      showSuccess('資料を生成しました');
      loadGenerationHistory();
      previewModal.style.display = 'none';
    }
  });

  // 配信実行
  executeDeliveryBtn.addEventListener('click', async () => {
    const channel = deliveryChannelSelect.value;
    const schedule = deliveryScheduleSelect.value;

    if (!channel) {
      showError('配信先を選択してください');
      return;
    }

    showSuccess(`${channel}で配信を実行しました`);
    deliveryChannelSelect.value = '';
    deliveryScheduleSelect.value = 'immediate';
  });

  // 配信スケジュール変更
  deliveryScheduleSelect.addEventListener('change', (e) => {
    const datetimePanel = container.querySelector('#schedule-datetime-panel');
    datetimePanel.style.display = e.target.value === 'scheduled' ? 'block' : 'none';
  });

  // 生成履歴読み込み
  async function loadGenerationHistory() {
    const history = await window.aivicApi.list(GENERATION_HISTORY_TABLE);
    if (!history || history.length === 0) {
      historyTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="5" style="padding: 12px; text-align: center; color: var(--text-muted);">履歴がありません</td></tr>';
      return;
    }

    historyTbody.innerHTML = history.slice(-10).reverse().map(h => `
      <tr style="border-bottom: 1px solid var(--border);">
        <td style="padding: 6px 8px;">${new Date(h.作成日時).toLocaleString('ja-JP')}</td>
        <td style="padding: 6px 8px;">${h.査定案件ID.substring(0, 8)}</td>
        <td style="padding: 6px 8px;">標準</td>
        <td style="padding: 6px 8px; color: #4caf50; font-weight: 500;">${h.生成ステータス}</td>
        <td style="padding: 6px 8px; text-align: center;">
          <button style="padding: 4px 8px; background: transparent; color: var(--text); border: 1px solid var(--border); border-radius: 3px; font-size: 12px; cursor: pointer;">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // モーダル閉じる
  container.querySelector('[data-testid="close-preview-button"]').addEventListener('click', () => {
    previewModal.style.display = 'none';
  });
  container.querySelector('[data-testid="close-preview-confirm-button"]').addEventListener('click', () => {
    previewModal.style.display = 'none';
  });
  container.querySelector('[data-testid="close-analysis-button"]').addEventListener('click', () => {
    analysisModal.style.display = 'none';
  });
  container.querySelector('[data-testid="close-analysis-confirm-button"]').addEventListener('click', () => {
    analysisModal.style.display = 'none';
  });

  // 通知表示
  function showSuccess(msg) {
    successMsg.textContent = msg;
    successMsg.style.display = 'block';
    setTimeout(() => { successMsg.style.display = 'none'; }, 3000);
  }

  function showError(msg) {
    errorMsg.textContent = msg;
    errorMsg.style.display = 'block';
    setTimeout(() => { errorMsg.style.display = 'none'; }, 3000);
  }

  // 初期化
  loadGenerationHistory();
}

function(container, apiUrl, tables) {
  // テーブルインデックスの定義
  const TABLE_ASSESSMENT = 0;      // 査定案件
  const TABLE_MARKET_DATA = 1;     // 相場データ
  const TABLE_DEVIATION = 2;       // 相場乖離分析
  const TABLE_EXPLANATION = 3;     // 説明資料
  const TABLE_DELIVERY = 4;        // 配信履歴

  let currentCaseId = null;
  let currentTemplate = null;
  let generatedMaterialId = null;
  let generationProgress = 0;

  // ===== DOM 要素の取得 =====
  const caseSelect = container.querySelector('[data-testid="assessment-case-select"]');
  const templateSelect = container.querySelector('[data-testid="template-select"]');
  const autoGraphCheckbox = container.querySelector('[data-testid="auto-graph-checkbox"]');
  const generateBtn = container.querySelector('[data-testid="generate-button"]');
  const deliveryEmailInput = container.querySelector('[data-testid="delivery-email-input"]');
  const deliverBtn = container.querySelector('[data-testid="deliver-button"]');
  const downloadBtn = container.querySelector('[data-testid="download-button"]');
  const viewMarketBtn = container.querySelector('[data-testid="view-market-data-btn"]');
  const previewContent = container.querySelector('#preview-content');
  const progressBar = container.querySelector('#progress-bar');
  const progressText = container.querySelector('#progress-text');
  const generationStatus = container.querySelector('#generation-status');
  const deliveryHistory = container.querySelector('#delivery-history');
  const marketModal = container.querySelector('#market-data-modal');
  const closeMarketModalBtn = container.querySelector('[data-testid="close-market-modal"]');
  const marketDataTbody = container.querySelector('#market-data-tbody');

  // ===== 初期化: 査定案件一覧を読み込み =====
  async function initAssessmentCases() {
    const cases = await window.aivicApi.list(TABLE_ASSESSMENT);
    if (!cases) return;

    // select に option を追加
    cases.forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id;
      opt.textContent = `${c.id.substring(0, 8)} - ${c.査定対象品名 || '(無名)'}`;
      caseSelect.appendChild(opt);
    });
  }

  // ===== 案件選択時: 相場乖離分析結果を表示 =====
  caseSelect.addEventListener('change', async (e) => {
    currentCaseId = e.target.value;
    if (!currentCaseId) {
      resetDeviationDisplay();
      return;
    }

    // 相場乖離分析データを取得
    const deviations = await window.aivicApi.list(TABLE_DEVIATION);
    if (!deviations) return;

    const deviation = deviations.find(d => d.査定案件ID === currentCaseId);
    if (deviation) {
      document.querySelector('#deviation-assessed-amount').textContent = 
        (deviation.査定金額 || 0).toLocaleString();
      document.querySelector('#deviation-market-amount').textContent = 
        (deviation.相場金額 || 0).toLocaleString();
      document.querySelector('#deviation-rate').textContent = 
        `${deviation.乖離率 || '0'}%`;
      document.querySelector('#deviation-category').textContent = 
        deviation.乖離区分 || '-';
    } else {
      resetDeviationDisplay();
    }

    // 配信ボタンを有効化
    deliverBtn.disabled = false;
  });

  function resetDeviationDisplay() {
    document.querySelector('#deviation-assessed-amount').textContent = '-';
    document.querySelector('#deviation-market-amount').textContent = '-';
    document.querySelector('#deviation-rate').textContent = '-';
    document.querySelector('#deviation-category').textContent = '-';
    deliverBtn.disabled = true;
  }

  // ===== 相場データ参照ボタン =====
  viewMarketBtn.addEventListener('click', async () => {
    const marketData = await window.aivicApi.list(TABLE_MARKET_DATA);
    if (!marketData) return;

    marketDataTbody.innerHTML = '';
    marketData.slice(0, 10).forEach(m => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.innerHTML = `
        <td style="padding: 8px; color: var(--text);">${m.品目コード || '-'}</td>
        <td style="padding: 8px; color: var(--text);">${m.品目名 || '-'}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${(m.相場単価 || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${(m.最低単価 || 0).toLocaleString()}</td>
        <td style="padding: 8px; text-align: right; color: var(--text);">${(m.最高単価 || 0).toLocaleString()}</td>
      `;
      marketDataTbody.appendChild(tr);
    });

    marketModal.style.display = 'flex';
  });

  closeMarketModalBtn.addEventListener('click', () => {
    marketModal.style.display = 'none';
  });

  marketModal.addEventListener('click', (e) => {
    if (e.target === marketModal) {
      marketModal.style.display = 'none';
    }
  });

  // ===== 自動生成実行 =====
  generateBtn.addEventListener('click', async () => {
    if (!currentCaseId) {
      alert('査定案件を選択してください');
      return;
    }
    if (!templateSelect.value) {
      alert('テンプレートを選択してください');
      return;
    }

    currentTemplate = templateSelect.value;
    generationProgress = 0;
    generatedMaterialId = null;

    // UI 更新
    generateBtn.disabled = true;
    generationStatus.textContent = '生成中...';
    previewContent.innerHTML = '<div style="color: var(--text-muted); text-align: center; padding: 40px;">生成処理を実行中です...</div>';
    downloadBtn.disabled = true;

    // 進捗シミュレーション
    const progressInterval = setInterval(() => {
      generationProgress += Math.random() * 25;
      if (generationProgress > 100) generationProgress = 100;

      progressBar.style.width = generationProgress + '%';
      progressText.textContent = Math.floor(generationProgress) + '%';

      if (generationProgress >= 100) {
        clearInterval(progressInterval);
        completeGeneration();
      }
    }, 600);
  });

  async function completeGeneration() {
    generationProgress = 100;
    progressBar.style.width = '100%';
    progressText.textContent = '100%';
    generationStatus.textContent = '✓ 生成完了';

    // 説明資料を保存
    const material = await window.aivicApi.save(TABLE_EXPLANATION, {
      査定案件ID: currentCaseId,
      資料タイプ: currentTemplate,
      資料タイトル: `${currentTemplate} - ${new Date().toLocaleString()}`,
      資料内容: generateSampleContent(currentTemplate),
      公開フラグ: true,
      作成者: 'system'
    });

    if (material) {
      generatedMaterialId = material.id;
      previewContent.innerHTML = `
        <div style="line-height: 1.8; color: var(--text);">
          <h4 style="margin: 0 0 12px 0; font-size: 14px; font-weight: 600;">📄 ${currentTemplate}</h4>
          <p style="margin: 0 0 8px 0; font-size: 12px; color: var(--text-muted);">
            生成日時: ${new Date().toLocaleString()}
          </p>
          <hr style="border: none; border-top: 1px solid var(--border); margin: 12px 0;" />
          <div style="font-size: 12px; white-space: pre-wrap; word-break: break-word;">
${generateSampleContent(currentTemplate)}
          </div>
        </div>
      `;
      downloadBtn.disabled = false;
    }

    generateBtn.disabled = false;
  }

  function generateSampleContent(templateType) {
    const templates = {
      'template-market-basis': `【相場根拠説明】

本査定は以下の相場データに基づいて実施されました。

■ 参照相場データ
  品目: 木製建具
  相場単価: 45,000円/m2
  適用地域: 全国
  出典: 物価本 2024年版

■ 査定結果
  査定金額: 48,500円/m2
  相場金額: 45,000円/m2
  乖離率: +7.8%

■ 乖離理由
  本案件は高級仕様の木製建具であり、標準相場より高い評価となっています。`,

      'template-deviation-analysis': `【乖離分析詳細】

査定結果と相場データの乖離を詳細に分析しました。

■ 乖離分析結果
  乖離金額: +3,500円/m2
  乖離率: +7.8%
  乖離区分: 高評価

■ 品質判定
  査定品質: 適正
  対応状況: 完了

■ 分析コメント
  本案件の乖離は品質向上による正当な評価差です。`,

      'template-adjustment-reason': `【調整理由書】

査定金額の調整理由を以下の通り説明いたします。

■ 調整内容
  調整前: 45,000円/m2
  調整後: 48,500円/m2
  調整額: +3,500円/m2

■ 調整理由
  1. 材料グレード: 標準品 → 高級品への変更
  2. 施工品質: 標準施工 → 丁寧施工への変更
  3. 市場動向: 2024年の相場上昇を反映

■ 根拠資料
  - 物価本 2024年版
  - 市場調査レポート`,

      'template-comparable': `【比較物件分析】

類似物件との比較分析を実施しました。

■ 比較物件1
  物件名: A社施工案件
  査定金額: 47,000円/m2
  評価: 標準的

■ 比較物件2
  物件名: B社施工案件
  査定金額: 50,000円/m2
  評価: 高級仕様

■ 本案件の位置付け
  本案件は比較物件1と2の中間的な評価となっており、
  市場相場として妥当な水準です。`
    };

    return templates[templateType] || '説明資料の内容がここに表示されます。';
  }

  // ===== PDFダウンロード =====
  downloadBtn.addEventListener('click', () => {
    if (!generatedMaterialId) return;

    const content = previewContent.innerText;
    const csv = `"説明資料"\n"${content.replace(/"/g, '""')}"`;
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `explanation_${new Date().getTime()}.csv`;
    link.click();
  });

  // ===== 配信実行 =====
  deliverBtn.addEventListener('click', async () => {
    const email = deliveryEmailInput.value.trim();
    if (!email) {
      alert('配信先メールアドレスを入力してください');
      return;
    }
    if (!generatedMaterialId) {
      alert('説明資料を生成してください');
      return;
    }

    deliverBtn.disabled = true;

    // 配信履歴を保存
    const delivery = await window.aivicApi.save(TABLE_DELIVERY, {
      査定案件ID: currentCaseId,
      ユーザーID: 'current-user',
      配信種別: '説明資料',
      配信チャネル: 'メール',
      配信ステータス: '送信済',
      配信日時: new Date().toISOString(),
      配信内容: `${currentTemplate} を ${email} に配信`,
      開封フラグ: false,
      作成者: 'system'
    });

    if (delivery) {
      alert('配信完了しました');
      addDeliveryHistoryItem(delivery);
      deliveryEmailInput.value = '';
    }

    deliverBtn.disabled = false;
  });

  function addDeliveryHistoryItem(delivery) {
    if (deliveryHistory.querySelector('[style*="text-align: center"]')) {
      deliveryHistory.innerHTML = '';
    }

    const item = document.createElement('div');
    item.style.cssText = `
      padding: 8px;
      margin-bottom: 8px;
      background: var(--bg-main);
      border-left: 3px solid var(--primary);
      border-radius: 4px;
      font-size: 11px;
      line-height: 1.5;
    `;
    item.innerHTML = `
      <div style="font-weight: 600; color: var(--text);">${delivery.配信種別}</div>
      <div style="color: var(--text-muted);">📧 ${delivery.配信内容}</div>
      <div style="color: var(--text-muted); margin-top: 4px;">
        ${new Date(delivery.配信日時).toLocaleString()}
      </div>
    `;
    deliveryHistory.insertBefore(item, deliveryHistory.firstChild);
  }

  // ===== 初期化実行 =====
  initAssessmentCases();

  // ===== キーボード操作: Esc でモーダルを閉じる =====
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && marketModal.style.display !== 'none') {
      marketModal.style.display = 'none';
    }
  });
}
